package it.frociart.app;
import java.util.*;import java.util.function.*;import static it.frociart.app.FlowModel.*;
/** Explicit read-only compiler schema. Fields and collections are materialized only when requested. */
final class FlowTemplateData {
    private FlowTemplateData(){}
    static final String[] TYPES={"auto","integer","real","text","boolean","void"};
    static final String[] KINDS={"start","end","process","decision","input","output","call","declare","openfile","readfile","writefile","closefile","turtleforward","turtleturn","turtlehome","turtleclear","turtlepen","pause","note"};
    static String safe(String name){StringBuilder b=new StringBuilder();for(char ch:(name==null?"":name).toCharArray())if(ch>='a'&&ch<='z'||ch>='A'&&ch<='Z'||ch>='0'&&ch<='9')b.append(ch);else b.append(String.format(Locale.ROOT,"_u%04x",(int)ch));return b.toString();}
    static FlowCodeTemplate.Deferred later(Supplier<Object> value){return new FlowCodeTemplate.Deferred(value);}
    static <T> List<Object> list(Collection<T> values,java.util.function.Function<T,Object> map){List<Object> result=new ArrayList<>();for(T value:values)result.add(map.apply(value));return result;}
    static FlowCodeTemplate.Data create(FlowSource.Program program){return new Builder(program).build();}
    static final class Builder {
        final FlowSource.Program program;final Map<String,String> functions=new HashMap<>();int budget;
        Builder(FlowSource.Program p){program=p;int index=0;for(FlowSource.Scope s:p.scopes)if(s.id!=null)functions.put(s.id,"function_"+(index++)+"_"+safe(s.name));}
        FlowCodeTemplate.Deferred later(Supplier<Object> value){if(++budget>32768)throw new IllegalArgumentException("I dati del modello superano il limite. Usa il campo source per il programma completo.");return new FlowCodeTemplate.Deferred(value);}
        FlowCodeTemplate.Data make(){return make(null);}FlowCodeTemplate.Data make(FlowSourceText.Origin origin){if(++budget>32768)throw new IllegalArgumentException("I dati del modello superano il limite. Usa il campo source per il programma completo.");return new FlowCodeTemplate.Data(origin);}
        FlowCodeTemplate.Data build(){List<Object> scopes=list(program.scopes,s->later(()->new Scope(this,s).build()));return make().put("schema",1d).put("title",program.title).put("scopes",scopes).put("main",scopes.get(0)).put("functions",new ArrayList<>(scopes.subList(1,scopes.size())));}
    }
    static final class Scope {
        final Builder owner;final FlowSource.Scope graph;final Map<String,FlowCodeTemplate.Deferred> blocks=new LinkedHashMap<>();final Map<String,String> symbols=new LinkedHashMap<>();List<String> collectedNames;FlowSourcePlan cachedPlan;
        Scope(Builder owner,FlowSource.Scope graph){this.owner=owner;this.graph=graph;for(FlowSource.Block b:graph.blocks)blocks.put(b.id,later(()->block(b)));}
        FlowCodeTemplate.Deferred later(Supplier<Object> value){return owner.later(value);}
        List<String> names(){if(collectedNames!=null)return collectedNames;List<String> result=new ArrayList<>();Consumer<String> add=name->{if(name!=null&&!symbols.containsKey(name.toLowerCase(Locale.ROOT))){symbols.put(name.toLowerCase(Locale.ROOT),"variable_"+result.size()+"_"+safe(name));result.add(name);}};for(FlowSource.Parameter p:graph.parameters)add.accept(p.name);for(FlowSource.Block b:graph.blocks){FlowSource.Operation o=b.operation;if(o.input!=null){add.accept(o.input.name);collect(o.input.index,add);}if(o.declaration!=null){for(String name:o.declaration.names)add.accept(name);collect(o.declaration.size,add);}for(FlowSource.Write w:o.writes){add.accept(w.target.name);collect(w.target.index,add);collect(w.value,add);}collect(o.value,add);}collectedNames=result;return result;}
        void collect(FlowSource.Expression e,Consumer<String> add){if(e==null)return;if(e.kind==FlowSource.ExpressionKind.Variable)add.accept(e.text);for(FlowSource.Expression c:e.children)collect(c,add);}
        String identifier(String name){if(name==null)return "";names();String value=symbols.get(name.toLowerCase(Locale.ROOT));if(value==null)throw new IllegalArgumentException("Simbolo del modello non trovato: "+name+".");return value;}
        FlowSourcePlan plan(){if(cachedPlan==null)cachedPlan=FlowSourcePlan.create(graph);return cachedPlan;}
        FlowCodeTemplate.Data build(){return owner.make().put("id",graph.id==null?"":graph.id).put("key",graph.id==null?"main":owner.functions.get(graph.id)).put("name",graph.name).put("isMain",graph.id==null).put("returns",graph.returnType!=VOID).put("returnType",TYPES[graph.returnType]).put("returnArray",graph.returnIsArray).put("returnVariable",graph.returnVariable==null?"":graph.returnVariable).put("returnIdentifier",later(()->graph.returnType==VOID?"":identifier(graph.returnVariable))).put("start",graph.startId)
            .put("symbolNames",later(()->new ArrayList<Object>(names()))).put("symbols",later(()->list(names(),n->later(()->owner.make().put("name",n).put("identifier",identifier(n))))))
            .put("parameters",later(()->list(graph.parameters,p->later(()->owner.make().put("name",p.name).put("identifier",identifier(p.name)).put("type",TYPES[p.type]).put("array",p.isArray).put("reference",p.byReference)))))
            .put("blocks",list(graph.blocks,b->blocks.get(b.id))).put("notes",list(graph.notes,n->later(()->block(n)))).put("structured",later(()->plan().structured)).put("statements",later(()->plan().structured?list(plan().statements,s->later(()->statement(s,0))):new ArrayList<>()));}
        FlowCodeTemplate.Data target(FlowSource.Target t,FlowSourceText.Origin origin){return t==null?null:owner.make(origin).put("name",t.name).put("identifier",later(()->identifier(t.name))).put("indexed",t.index!=null).put("index",later(()->expression(t.index,origin,0)));}
        FlowCodeTemplate.Data expression(FlowSource.Expression e,FlowSourceText.Origin origin,int depth){if(e==null)return null;if(depth>256)throw new IllegalArgumentException("L’espressione supera la profondità del modello.");return owner.make(origin).put("kind",e.kind.toString().toLowerCase(Locale.ROOT)).put("text",e.text==null?"":e.text).put("number",e.number).put("bits",String.format(Locale.ROOT,"%016x",Double.doubleToLongBits(e.number))).put("boolean",e.bool).put("functionId",e.functionId==null?"":e.functionId).put("functionKey",e.functionId==null?"":owner.functions.get(e.functionId)).put("identifier",later(()->e.kind==FlowSource.ExpressionKind.Variable?identifier(e.text):""))
            .put("isNumber",e.kind==FlowSource.ExpressionKind.Number).put("isText",e.kind==FlowSource.ExpressionKind.Text).put("isBoolean",e.kind==FlowSource.ExpressionKind.Boolean).put("isVariable",e.kind==FlowSource.ExpressionKind.Variable).put("isVector",e.kind==FlowSource.ExpressionKind.Vector).put("isIndex",e.kind==FlowSource.ExpressionKind.Index).put("isUnary",e.kind==FlowSource.ExpressionKind.Unary).put("isBinary",e.kind==FlowSource.ExpressionKind.Binary).put("isCall",e.kind==FlowSource.ExpressionKind.Call).put("children",later(()->list(e.children,c->later(()->expression(c,origin,depth+1)))));}
        FlowCodeTemplate.Data declaration(FlowSource.Declaration d,FlowSourceText.Origin origin){return d==null?null:owner.make(origin).put("type",TYPES[d.type]).put("array",d.isArray()).put("size",later(()->expression(d.size,origin,0))).put("names",list(d.names,n->later(()->owner.make(origin).put("name",n).put("identifier",later(()->identifier(n))))));}
        FlowCodeTemplate.Data block(FlowSource.Block b){FlowSourceText.Origin origin=new FlowSourceText.Origin(graph.id,b.id);FlowSource.Operation o=b.operation;return owner.make(origin).put("id",b.id).put("kind",KINDS[b.kind]).put("text",b.text).put("prompt",b.prompt==null?"":b.prompt).put("comment",b.comment==null?"":b.comment).put("reachable",b.reachable)
            .put("isStart",b.kind==START).put("isEnd",b.kind==END).put("isInput",b.kind==INPUT).put("isOutput",b.kind==OUTPUT).put("isProcess",b.kind==PROCESS).put("isDecision",b.kind==DECISION).put("isDeclare",b.kind==DECLARE).put("isCall",b.kind==CALL).put("isNote",b.kind==NOTE).put("isPause",b.kind==PAUSE)
            .put("input",later(()->target(o.input,origin))).put("value",later(()->expression(o.value,origin,0))).put("declaration",later(()->declaration(o.declaration,origin))).put("writes",later(()->list(o.writes,w->later(()->owner.make(origin).put("target",later(()->target(w.target,origin))).put("value",later(()->expression(w.value,origin,0)))))))
            .put("links",later(()->list(b.links,l->later(()->owner.make(origin).put("id",l.id).put("to",l.to).put("branch",l.branch))))).put("next",b.next("next")==null?"":b.next("next")).put("yes",b.next("true")==null?"":b.next("true")).put("no",b.next("false")==null?"":b.next("false")).put("fileReading",o.fileReading).put("fileNewline",o.fileNewline).put("turtleDraw",o.turtleDraw).put("turtleLeft",o.turtleLeft).put("outputNewline",o.outputNewline);}
        FlowCodeTemplate.Data statement(FlowSourcePlan.Statement s,int depth){if(depth>64)throw new IllegalArgumentException("Il piano supera la profondità del modello.");return owner.make(new FlowSourceText.Origin(graph.id,s.block.id)).put("kind",s.kind.toString().toLowerCase(Locale.ROOT)).put("instruction",s.kind==FlowSourcePlan.Kind.Instruction).put("conditional",s.kind==FlowSourcePlan.Kind.If).put("loop",s.kind==FlowSourcePlan.Kind.While||s.kind==FlowSourcePlan.Kind.Repeat).put("postTest",s.kind==FlowSourcePlan.Kind.Repeat).put("entryBlock",blocks.get(s.entryBlock().id)).put("loopOnTrue",s.loopOnTrue).put("block",blocks.get(s.block.id)).put("body",list(s.body,n->later(()->statement(n,depth+1)))).put("otherwise",list(s.otherwise,n->later(()->statement(n,depth+1))));}
    }
}
